args.CommandLine:
"Get-ChildItem -Path "d:\项目session\blender-supercar" -Directory | ForEach-Object {
    $dir = $_
    $files = Get-ChildItem -Path $dir.FullName -Recurse -File
    $size = ($files | Measure-Object -Property Length -Sum).Sum
    [PSCustomObject]@{
        Directory = $dir.Name
        FileCount = $files.Count
        SizeMB = [math]::Round($size / 1MB, 2)
    }
}"

"& "d:\APPs\steam\steamapps\common\Blender\blender.exe" -b "d:\项目session\blender-supercar\scifi_f1_2035_v4_racing.blend" --python-expr "import bpy
for m in bpy.data.materials:
    if m.use_nodes and m.node_tree:
        for node in m.node_tree.nodes:
            if node.type == 'TEX_IMAGE' and node.image:
                print(f'{m.name} -> {node.image.name} ({node.image.filepath})')
""
